def soil_development_index(clay_content, base_saturation, organic_matter):
    product = clay_content * base_saturation * organic_matter
    if product <= 0.0:
        return 0.0
    return (product) ** (1.0 / 3.0)



def clay_illuviation_ratio(bt_clay_pct, eluvial_clay_pct):
    if eluvial_clay_pct <= 0.0:
        return 0.0
    return bt_clay_pct / eluvial_clay_pct



def rubification_index(munsell_hue_number, chroma, value):
    if value <= 0.0:
        return 0.0
    return (10.0 - munsell_hue_number) * chroma / value



def organic_horizon_depth(litter_input_g_m2_yr, decomposition_rate):
    if decomposition_rate <= 0.0:
        return 0.0
    mass = litter_input_g_m2_yr / decomposition_rate
    return mass / 100.0  # assume 100 g/m² per cm



def base_saturation_percent(sum_bases_cmol_kg, cec_cmol_kg):
    if cec_cmol_kg <= 0.0:
        return 0.0
    return sum_bases_cmol_kg / cec_cmol_kg * 100.0



def solum_thickness_estimate(precipitation_mm_yr, temperature_c, age_kyr):
    if temperature_c <= 0.0:
        return 0.0
    return 0.8 * (precipitation_mm_yr / temperature_c) * math.log(age_kyr + 1.0)



def profile_development_index(clay_increase, structure_grade, horizon_thickness_cm):
    return clay_increase * structure_grade * horizon_thickness_cm



def biological_weathering_index(root_density_km_m3, lichen_cover_pct):
    return root_density_km_m3 * lichen_cover_pct / 100.0



def translocation_coefficient(element_subsoil, element_topsoil):
    if element_topsoil <= 0.0:
        return 0.0
    return element_subsoil / element_topsoil



def soil_age_from_pedogenesis(observed_pdi, pdi_rate):
    if pdi_rate <= 0.0:
        return 0.0
    return observed_pdi / pdi_rate
